const HTML = "<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#153e44\"><title>Meu PPR e Dobras • Simulador</title><style>\n:root{font-family:system-ui,sans-serif;color:#163b40;background:#f1f5f4;font-size:16px}*{box-sizing:border-box}body{margin:0}header{background:#153e44;color:white;padding:32px max(20px,calc((100vw - 1000px)/2)) 65px}header small{color:#cedb77;letter-spacing:2px;font-weight:700}h1{font-size:clamp(30px,6vw,44px);margin:12px 0}header p{color:#d3e2e1;max-width:600px;line-height:1.6}main{max-width:1000px;margin:-30px auto 40px;padding:0 16px;display:grid;grid-template-columns:1.2fr 1fr;gap:20px;align-items:start}.card{background:white;padding:26px;border-radius:20px;box-shadow:0 5px 25px #153e440b}h2{font-size:20px;margin:0 0 20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}label{display:block;font-size:14px;font-weight:650;margin-bottom:7px}input,select{font:inherit;width:100%;padding:12px;border:1px solid #bccdce;border-radius:10px;background:#fff;color:#163b40}input:focus,select:focus{outline:3px solid #c7d951;outline-offset:2px}.hint{display:block;font-size:12px;color:#566e72;line-height:1.5;margin-top:6px}button{font:inherit;font-weight:700;background:#c8dd54;color:#153e44;border:0;border-radius:12px;padding:16px;width:100%;cursor:pointer}button:hover{background:#b9d137}.notice{font-size:13px;background:#f4f6e8;padding:14px;border-radius:10px;line-height:1.6;margin:18px 0}.amount{font-size:clamp(30px,5vw,42px);font-weight:750;margin:8px 0 22px;overflow-wrap:anywhere}.muted{color:#566e72;font-size:14px;line-height:1.6}.breakdown{margin:0}.breakdown div{display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid #e6edec;font-size:14px}.breakdown dd{margin:0;text-align:right;font-weight:650}.formula{margin-top:22px;font-size:13px;line-height:1.7;border-left:3px solid #c8dd54;padding-left:12px}details{margin-top:22px}summary{font-weight:650;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:13px;margin:15px 0}th,td{padding:9px;text-align:left;border-bottom:1px solid #e6edec}.error{color:#a12626;font-weight:600}footer{text-align:center;font-size:12px;color:#566e72;padding:0 20px 25px} [hidden]{display:none!important}@media(max-width:700px){main{grid-template-columns:1fr}.card{padding:22px}.grid{gap:15px}header{padding-top:24px}.amount{font-size:36px}}@media(max-width:360px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}@media print{header{padding:15px;background:none;color:#163b40}header p,button,details,footer{display:none}main{display:block;margin:0}.card{box-shadow:none;border:1px solid #ccc;margin:15px 0}}\n.tabs{grid-column:1/-1;display:flex;gap:8px;background:white;padding:8px;border-radius:16px}.tabs button{background:transparent;padding:13px 6px;min-width:0;flex:1}.tabs{gap:5px;padding:6px}.tabs button,.tabs a{font-size:clamp(11px,2.7vw,14px);line-height:1.25}.tabs button[aria-pressed=\"true\"]{background:#153e44;color:white}.tabs #aba-senior[data-active=\"true\"]{background:#153e44!important;color:white!important}.panel{display:contents}.night{display:flex;gap:10px;align-items:center}.night input{width:20px;height:20px;accent-color:#153e44}.night label{margin:0}.total-dobra{font-size:32px;font-weight:750;margin:8px 0}.result-card{padding:16px;background:#f1f5f4;border-radius:12px;margin:14px 0}.result-card p{margin:4px 0;font-size:14px}\nheader{position:relative;isolation:isolate}header::before{content:'';position:absolute;inset:0;z-index:-1;background-image:url(data:image/webp;base64,);background-size:cover;background-position:center 55%;opacity:.28;pointer-events:none}header h1,header p,header small{text-shadow:0 1px 4px #082b30}main{position:relative}\n.brand-line{display:flex;align-items:center;gap:12px}.brand-icon{width:58px;height:58px;object-fit:contain;background:transparent;border-radius:0;padding:0;flex-shrink:0}.brand-line small{line-height:1.5}@media(max-width:400px){.brand-icon{width:48px;height:48px}.brand-line{gap:10px}.brand-line small{font-size:10px;letter-spacing:1.4px}}\n#painel-escala select{background:#fff;border:1px solid #9dbab5;border-radius:14px;color:#153e44;font-weight:650}#painel-escala #escala-grade-futuro>div{border-radius:12px!important}#painel-escala #escala-proximo-futuro,#painel-escala #escala-anterior-futuro{border-radius:16px!important;font-weight:750}#painel-escala h2{font-size:clamp(22px,4.5vw,30px)}\n/* Escala: tema preto fosco e borda cromada */\nbody:has(#painel-escala:not([hidden])){background:#101010;color:#f6f6f6}\nbody:has(#painel-escala:not([hidden])) footer{color:#d1d1d1}\n#painel-escala>.card{background:#141414!important;border:7px solid #DCDCDC!important;color:#f7f7f7!important;box-shadow:0 5px 25px #0005!important}\n#painel-escala>.card h2,#painel-escala>.card label,#painel-escala>.card #escala-folgas-futuro{color:#f7f7f7!important}\n#painel-escala>.card .muted{color:#dedede!important}\n#painel-escala #escala-anterior-futuro{background:#383838!important;color:#fff!important}\n#painel-escala #escala-proximo-futuro{background:#07545c!important;color:#fff!important}\n#painel-escala #escala-ano-futuro,#painel-escala #escala-mes-futuro{background:#fff!important;color:#161616!important;border-color:#dcdcdc!important}\n</style><link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"icon\" type=\"image/png\" href=\"/icons/terberg-v4-192.png\"><link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"/apple-touch-icon.png?v=4\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\"><meta name=\"apple-mobile-web-app-title\" content=\"Meu PPR\"></head><body><header><div class=\"brand-line\"><img class=\"brand-icon\" width=\"512\" height=\"512\" src=\"data:image/webp;base64,\" alt=\"Caminhão de terminal Terberg\"><small>SEU TRABALHO, SEUS RESULTADOS</small></div><h1>Meu PPR e Dobras</h1><p>Seu salário como base para simular o PPR e o valor de uma dobra.</p></header><main><nav class=\"tabs\" aria-label=\"Calculadoras e acesso Senior\" style=\"display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto auto;gap:8px;font-size:18px\"><button id=\"aba-ppr\" type=\"button\" aria-pressed=\"true\" aria-controls=\"painel-ppr\" style=\"grid-column:1;grid-row:1;font-size:18px;font-weight:750\">PPR</button><a id=\"aba-senior\" href=\"https://platform.senior.com.br/login/?redirectTo=https://platform.senior.com.br/senior-x/&amp;tenant=btp.com.br\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"grid-column:1;grid-row:2;display:flex;align-items:center;justify-content:center;padding:13px 6px;border-radius:12px;background:#e9f0f0;color:#153e44;font-weight:700;text-decoration:none;font-size:18px\">SENIOR</a><button id=\"aba-dobra\" type=\"button\" aria-pressed=\"false\" aria-controls=\"painel-dobra\" style=\"grid-column:2;grid-row:1 / 3;font-size:18px;font-weight:750\">Dobra / horas extras</button><button id=\"aba-escala\" type=\"button\" aria-pressed=\"false\" aria-controls=\"painel-escala\" style=\"grid-column:1/-1;grid-row:3;font-size:18px;font-weight:750\">ESCALA</button></nav><div class=\"panel\" id=\"painel-escala\" hidden><section class=\"card\" style=\"grid-column:1/-1;background:linear-gradient(135deg,#e6f3f0 0%,#d8ece7 100%);border:7px solid #ffffff;border-radius:26px;box-shadow:0 5px 25px #153e4412\"><h2>ESCALA — Equipe A</h2><p class=\"muted\">Selecione o ano e o mês para consultar os turnos e as folgas. A escala de 2027 está aprovada.</p><div style=\"display:grid;grid-template-columns:1fr 2fr;gap:8px;margin:14px 0\"><label style=\"font-weight:700\">Ano<select id=\"escala-ano-futuro\" style=\"width:100%;margin-top:5px\"><option>2027</option><option>2028</option><option>2029</option><option>2030</option></select></label><label style=\"font-weight:700\">Mês<select id=\"escala-mes-futuro\" style=\"width:100%;margin-top:5px\"><option value=\"0\">Janeiro</option><option value=\"1\">Fevereiro</option><option value=\"2\">Março</option><option value=\"3\">Abril</option><option value=\"4\">Maio</option><option value=\"5\">Junho</option><option value=\"6\">Julho</option><option value=\"7\">Agosto</option><option value=\"8\">Setembro</option><option value=\"9\">Outubro</option><option value=\"10\">Novembro</option><option value=\"11\">Dezembro</option></select></label></div><h3 id=\"escala-titulo-futuro\" style=\"text-align:center;margin:16px 0\"></h3><div id=\"escala-grade-futuro\" style=\"display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px\"></div><div style=\"display:flex;flex-wrap:wrap;gap:7px;margin:14px 0\"><span style=\"display:inline-flex;align-items:center;gap:4px;font-size:12px\"><i style=\"display:inline-block;width:13px;height:13px;border:1px solid #9aafb0;border-radius:3px;background:#f4d94b\"></i>19h–01h</span><span style=\"display:inline-flex;align-items:center;gap:4px;font-size:12px\"><i style=\"display:inline-block;width:13px;height:13px;border:1px solid #9aafb0;border-radius:3px;background:#59c579\"></i>13h–19h</span><span style=\"display:inline-flex;align-items:center;gap:4px;font-size:12px\"><i style=\"display:inline-block;width:13px;height:13px;border:1px solid #9aafb0;border-radius:3px;background:#5abbe7\"></i>07h–13h</span><span style=\"display:inline-flex;align-items:center;gap:4px;font-size:12px\"><i style=\"display:inline-block;width:13px;height:13px;border:1px solid #9aafb0;border-radius:3px;background:#e9acd2\"></i>01h–07h</span><span style=\"display:inline-flex;align-items:center;gap:4px;font-size:12px\"><i style=\"display:inline-block;width:13px;height:13px;border:1px solid #9aafb0;border-radius:3px;background:#f1f5f4\"></i>Folga</span></div><p id=\"escala-folgas-futuro\" style=\"font-weight:700\"></p><p class=\"muted\" id=\"escala-status-futuro\"></p><div style=\"display:flex;justify-content:space-between;gap:8px\"><button id=\"escala-anterior-futuro\" type=\"button\" style=\"padding:10px 16px;background:#e9f0f0;color:#153e44\">← Anterior</button><button id=\"escala-proximo-futuro\" type=\"button\" style=\"padding:10px 16px;background:#153e44;color:white\">Próximo →</button></div></section></div><div class=\"panel\" id=\"painel-ppr\"><section class=\"card\"><h2>Dados da simulação</h2><form id=\"form\"><div class=\"grid\">\n<div class=\"full\"><label for=\"salario\">Salário-base de dezembro/2026 (R$)</label><input id=\"salario\" type=\"text\" inputmode=\"decimal\" placeholder=\"Ex.: 4.500,00\" required></div>\n<div class=\"full\"><label for=\"adicionais\">Adicionais permitidos — valor total (R$)</label><input id=\"adicionais\" type=\"text\" inputmode=\"decimal\" value=\"0\" required><small class=\"hint\">Insalubridade, periculosidade, acúmulo de função ou condução. O adicional de turno não entra na base do PPR.</small></div>\n<div><label for=\"target\">Target (nº de salários)</label><input id=\"target\" type=\"number\" inputmode=\"decimal\" min=\"0\" step=\"0.001\" placeholder=\"Informe o target\" required><small class=\"hint\">Multiplicador informado pela empresa.</small></div>\n<div><label for=\"meses\">Meses considerados</label><select id=\"meses\"><option value=\"0\">0 de 12 meses</option><option value=\"1\">1 de 12 meses</option><option value=\"2\">2 de 12 meses</option><option value=\"3\">3 de 12 meses</option><option value=\"4\">4 de 12 meses</option><option value=\"5\">5 de 12 meses</option><option value=\"6\">6 de 12 meses</option><option value=\"7\">7 de 12 meses</option><option value=\"8\">8 de 12 meses</option><option value=\"9\">9 de 12 meses</option><option value=\"10\">10 de 12 meses</option><option value=\"11\">11 de 12 meses</option><option value=\"12\" selected>12 de 12 meses</option></select><small class=\"hint\">15 dias trabalhados no mês contam como um avo.</small></div>\n<div><label for=\"reducao\">Redução total confirmada (%)</label><input id=\"reducao\" type=\"number\" inputmode=\"decimal\" min=\"0\" max=\"100\" step=\"0.01\" value=\"0\" required><small class=\"hint\">Consulte os critérios abaixo. A combinação de faltas e sanções ainda precisa ser confirmada.</small></div>\n<div class=\"full\"><label for=\"gatilho\">Gatilho de EBITDA atingiu pelo menos 80%?</label><select id=\"gatilho\"><option value=\"sim\">Sim — simular pagamento</option><option value=\"nao\">Não — PPR não é ativado</option><option value=\"pendente\">Ainda não foi divulgado</option></select></div></div>\n<div class=\"notice\">Simulação para colaborador ativo e elegível. O multiplicador do PPR deve ser informado conforme a divulgação da empresa. Desligamentos e afastamentos exigem análise das regras específicas.</div><button type=\"submit\">Calcular meu PPR</button><p id=\"erro\" class=\"error\" role=\"alert\" hidden></p></form>\n<details><summary>Critérios do material PPR 2026</summary><p class=\"muted\">Os percentuais abaixo são referências separadas. O simulador não soma automaticamente faltas e sanções.</p><table><thead><tr><th>Sanções disciplinares</th><th>Perda</th></tr></thead><tbody><tr><td>1 advertência</td><td>10%</td></tr><tr><td>2 advertências</td><td>20%</td></tr><tr><td>3 advertências</td><td>40%</td></tr><tr><td>4 ou mais advertências</td><td>50%</td></tr><tr><td>1 suspensão ou mais</td><td>50%</td></tr></tbody></table><table><thead><tr><th>Faltas injustificadas</th><th>Perda</th></tr></thead><tbody><tr><td>1 falta</td><td>10%</td></tr><tr><td>2 faltas</td><td>20%</td></tr><tr><td>3 faltas</td><td>40%</td></tr><tr><td>4 ou mais faltas</td><td>50%</td></tr></tbody></table><p class=\"muted\">A advertência pela própria falta injustificada não gera penalização em duplicidade por falta + advertência.</p></details></section>\n<aside class=\"card\" aria-live=\"polite\" aria-atomic=\"true\"><h2>Seu resultado</h2><div id=\"vazio\"><p class=\"muted\">Preencha os dados e toque em calcular para ver sua estimativa.</p><div class=\"formula\">Base salarial × target × meses ÷ 12 × (1 − redução)</div></div><div id=\"resumo\" hidden><span class=\"muted\">PPR bruto estimado</span><div class=\"amount\" id=\"total\"></div><dl class=\"breakdown\" id=\"etapas\"></dl><p id=\"estado\" class=\"notice\"></p><p class=\"muted\">Valor antes de eventual imposto de renda. Não representa um valor líquido garantido.</p></div></aside></div><div class=\"panel\" id=\"painel-dobra\" hidden><section class=\"card\"><h2>Quanto vale uma dobra?</h2><p class=\"muted\">Calcule de 1 a 12 horas extras, além do seu turno normal.</p><form id=\"form-dobra\"><label for=\"salario-dobra\">Salário-base mensal (R$)</label><input id=\"salario-dobra\" type=\"text\" inputmode=\"decimal\" placeholder=\"Ex.: 4.500,00\" required><p class=\"hint\">Hora normal = salário ÷ 180 horas mensais.</p><label for=\"total-horas\">Quantidade de horas extras</label><select id=\"total-horas\"><option value=\"1\">1 hora</option><option value=\"2\">2 horas</option><option value=\"3\">3 horas</option><option value=\"4\">4 horas</option><option value=\"5\">5 horas</option><option value=\"6\" selected>6 horas</option><option value=\"7\">7 horas</option><option value=\"8\">8 horas</option><option value=\"9\">9 horas</option><option value=\"10\">10 horas</option><option value=\"11\">11 horas</option><option value=\"12\">12 horas</option></select><div class=\"notice\"><div class=\"night\"><input id=\"noturno-dobra\" type=\"checkbox\"><label for=\"noturno-dobra\">Dobra com adicional noturno</label></div><div id=\"seletor-noturno\" hidden style=\"margin-top:16px\"><label for=\"horas-noturnas\">Quantas horas extras são noturnas?</label><select id=\"horas-noturnas\"><option value=\"6\">6 horas — período inteiro</option><option value=\"5\">5 horas</option><option value=\"4\">4 horas</option><option value=\"3\">3 horas</option><option value=\"2\">2 horas</option><option value=\"1\">1 hora</option></select><small class=\"hint\">Turnos com noturno: 19h à 01h e 01h às 07h. Adicional noturno fixo de 50% em dia comum e feriado. Informe apenas as horas extras dentro desses turnos.</small></div></div><label for=\"dsr-percentual\" style=\"margin-top:16px\">DSR estimado (%)</label><input id=\"dsr-percentual\" type=\"number\" inputmode=\"decimal\" min=\"0\" max=\"100\" step=\"0.01\" value=\"20\"><small class=\"hint\">Percentual ajustável para simulação dos reflexos de DSR (Códs. 265 e 268). O valor real varia conforme o calendário e as regras da empresa.</small><button type=\"submit\">Calcular minha dobra</button><p id=\"erro-dobra\" class=\"error\" role=\"alert\" hidden></p></form><div class=\"formula\">Cálculo por rubrica separada: Cód. 257 (hora extra 50%) ou Cód. 259 (hora extra 100%) + Cód. 1950 (adicional noturno fixo de 50% sobre a hora normal), apenas nas horas noturnas de 19h à 01h e 01h às 07h. Reflexos de DSR: Códs. 265 e 268, apresentados apenas como estimativa.</div></section><aside class=\"card\" aria-live=\"polite\" aria-atomic=\"true\"><h2>Valor da dobra</h2><p id=\"vazio-dobra\" class=\"muted\">Informe seu salário para comparar a dobra em dia comum e em feriado.</p><div id=\"resumo-dobra\" hidden><p id=\"base-dobra\" class=\"muted\"></p><div class=\"result-card\"><p>Hora extra de 50% · dia comum</p><div class=\"total-dobra\" id=\"total-50\"></div><p id=\"detalhe-50\"></p></div><div class=\"result-card\"><p>Hora extra de 100% · feriado</p><div class=\"total-dobra\" id=\"total-100\"></div><p id=\"detalhe-100\"></p></div><div class=\"result-card\"><p><strong>DSR — valor estimado, não é valor real de pagamento</strong></p><p id=\"dsr-taxa\"></p><p id=\"dsr-50\"></p><p id=\"dsr-100\"></p><p id=\"com-dsr-50\"></p><p id=\"com-dsr-100\"></p><small class=\"hint\">Simulação apenas. O valor do holerite pode ser diferente.</small></div><h3 style=\"font-size:18px;margin-top:24px\">Quanto vale 1 hora?</h3><table><thead><tr><th scope=\"col\">Tipo de hora</th><th scope=\"col\">Valor bruto</th></tr></thead><tbody><tr><th scope=\"row\">Hora normal</th><td id=\"hora-normal\"></td></tr><tr><th scope=\"row\">Hora extra a 50%</th><td id=\"hora-50\"></td></tr><tr><th scope=\"row\">Hora extra a 100%</th><td id=\"hora-100\"></td></tr><tr><th scope=\"row\">Hora extra a 50% + noturno de 50%</th><td id=\"hora-noturna-50\"></td></tr><tr><th scope=\"row\">Hora extra a 100% + noturno de 50%</th><td id=\"hora-noturna-100\"></td></tr></tbody></table><small class=\"hint\">Valores completos de 1 hora, incluindo os adicionais indicados. Os dois exemplos com noturno aparecem sempre para comparação; o total da dobra usa a opção que você marcou. Arredondamento apenas na exibição.</small><p id=\"periodo-dobra\" class=\"notice\"></p><p class=\"muted\">Nota 1: Quando o feriado cai no domingo, aplica-se o teto de 100% (não acumula para 200%), conforme a regra informada. Nota 2: Valores brutos. O DSR apresentado é apenas uma estimativa configurável, não é um valor real de pagamento. O valor efetivo depende do calendário e das regras aplicáveis. Cálculo por hora de relógio, sem ajuste de hora noturna reduzida.</p></div></aside></div></main><footer>Meu PPR e Dobras · Simulador independente baseado no material enviado do PPR BTP 2026.</footer>\n<script>\nconst money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});\n\nfunction lerDinheiro(valor){\n const s=String(valor).trim().replace(/^R\\$\\s*/, '');\n let normalizado;\n if(/^\\d{1,3}(\\.\\d{3})+(,\\d{1,2})?$/.test(s))normalizado=s.replace(/\\./g,'').replace(',','.');\n else if(/^\\d+(,\\d{1,2})?$/.test(s))normalizado=s.replace(',','.');\n else if(/^\\d+\\.\\d{1,2}$/.test(s))normalizado=s;\n else throw Error('Informe o dinheiro no formato 4.500,00 ou 4500.');\n const n=Number(normalizado);if(!Number.isFinite(n)||n<0)throw Error('Informe um valor de dinheiro válido.');return n;\n}\n\nfunction calcularPPR(d){\n for(const key of ['salario','adicionais','target','meses','reducao']){if(!Number.isFinite(d[key])||d[key]<0)throw Error('Preencha todos os valores com números válidos.');}\n if(d.salario<=0||!Number.isInteger(d.meses)||d.meses>12||d.reducao>100||!['sim','nao','pendente'].includes(d.gatilho))throw Error('Confira salário, meses e redução (de 0% a 100%).');\n const base=d.salario+d.adicionais,meta=base*d.target,proporcional=meta*d.meses/12,desconto=proporcional*d.reducao/100;\n const total=d.gatilho==='nao'?0:proporcional-desconto;\n if(![base,meta,proporcional,desconto,total].every(Number.isFinite))throw Error('Os valores informados excedem o limite do cálculo.');\n return {base,meta,proporcional,desconto,total};\n}\ndocument.getElementById('form').addEventListener('submit',event=>{event.preventDefault();const erro=document.getElementById('erro');try{const d=Object.fromEntries(['salario','adicionais','target','meses','reducao'].map(id=>[id,['salario','adicionais'].includes(id)?lerDinheiro(document.getElementById(id).value):Number(document.getElementById(id).value)]));d.gatilho=document.getElementById('gatilho').value;const r=calcularPPR(d);document.getElementById('total').textContent=money(r.total);const rows=[['Base salarial com adicionais',money(r.base)],['Target',d.target.toLocaleString('pt-BR')+' salário(s)'],['Antes da proporcionalidade',money(r.meta)],['Proporcional ('+d.meses+'/12)',money(r.proporcional)],['Redução ('+d.reducao+'%)','− '+money(r.desconto)]];const etapas=document.getElementById('etapas');etapas.replaceChildren();for(const [label,value]of rows){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);etapas.append(row);}document.getElementById('estado').textContent=d.gatilho==='nao'?'Gatilho não atingido: PPR não ativado.':d.gatilho==='pendente'?'Cenário hipotético: o gatilho de EBITDA ainda não foi confirmado.':'Estimativa com os parâmetros que você informou.';document.getElementById('vazio').hidden=true;document.getElementById('resumo').hidden=false;erro.hidden=true;}catch(e){erro.textContent=e.message;erro.hidden=false;document.getElementById('resumo').hidden=true;}});\ndocument.getElementById('form').addEventListener('input',()=>{document.getElementById('resumo').hidden=true;document.getElementById('vazio').hidden=false;});\n\nfunction calcularDobra(salario,horasNoturnas=0,totalHoras=6){\n if(!Number.isFinite(salario)||salario<=0||!Number.isInteger(horasNoturnas)||horasNoturnas<0||horasNoturnas>totalHoras||!Number.isInteger(totalHoras)||totalHoras<1||totalHoras>12)throw Error('Informe um salário válido, de 1 a 12 horas extras e horas noturnas dentro do total.');\n const hora=salario/180,porHora50=hora*1.5,porHora100=hora*2,porHoraNoturna50=hora*2,porHoraNoturna100=hora*2.5;\n const he50=totalHoras*porHora50,he100=totalHoras*porHora100,noturno50=horasNoturnas*hora*.5,noturno100=horasNoturnas*hora*.5;\n const total50=he50+noturno50,total100=he100+noturno100;\n if(![total50,total100].every(Number.isFinite))throw Error('O salário informado excede o limite do cálculo.');\n return {hora,total50,total100,porHora50,porHora100,porHoraNoturna50,porHoraNoturna100,he50,he100,noturno50,noturno100};\n}\nfor(const aba of ['ppr','dobra','escala'])document.getElementById('aba-'+aba).addEventListener('click',()=>{document.getElementById('aba-senior').removeAttribute('data-active');for(const nome of ['ppr','dobra','escala']){document.getElementById('painel-'+nome).hidden=nome!==aba;document.getElementById('aba-'+nome).setAttribute('aria-pressed',String(nome===aba));}});document.getElementById('aba-senior').addEventListener('click',()=>{document.getElementById('aba-senior').setAttribute('data-active','true');for(const nome of ['ppr','dobra','escala'])document.getElementById('aba-'+nome).setAttribute('aria-pressed','false');});\nconst limparDobra=()=>{document.getElementById('resumo-dobra').hidden=true;document.getElementById('vazio-dobra').hidden=false;document.getElementById('erro-dobra').hidden=true;};\ndocument.getElementById('noturno-dobra').addEventListener('change',()=>{document.getElementById('seletor-noturno').hidden=!document.getElementById('noturno-dobra').checked;limparDobra();});\ndocument.getElementById('form-dobra').addEventListener('input',limparDobra);\nfor(const [origem,destino]of [['salario','salario-dobra'],['salario-dobra','salario']])document.getElementById(origem).addEventListener('input',()=>{document.getElementById(destino).value=document.getElementById(origem).value;limparDobra();document.getElementById('resumo').hidden=true;document.getElementById('vazio').hidden=false;});\ndocument.getElementById('form-dobra').addEventListener('submit',event=>{event.preventDefault();try{const salario=lerDinheiro(document.getElementById('salario-dobra').value),t=Number(document.getElementById('total-horas').value),n=document.getElementById('noturno-dobra').checked?Number(document.getElementById('horas-noturnas').value):0;const r=calcularDobra(salario,n,t);document.getElementById('base-dobra').textContent='Hora normal: '+money(r.hora)+' · Divisor: 180 horas';document.getElementById('total-50').textContent=money(r.total50);document.getElementById('total-100').textContent=money(r.total100);for(const [id,key]of [['hora-normal','hora'],['hora-50','porHora50'],['hora-100','porHora100'],['hora-noturna-50','porHoraNoturna50'],['hora-noturna-100','porHoraNoturna100']])document.getElementById(id).textContent=money(r[key]);for(const taxa of [50,100]){const normal=r['porHora'+taxa],noturna=r['porHoraNoturna'+taxa];document.getElementById('detalhe-'+taxa).textContent='Cód. '+(taxa===50?'257':'259')+' — Hora Extra: '+money(r['he'+taxa])+' | Cód. 1950 — Adic. Noturno 50%: '+money(r['noturno'+taxa]);}const dsrPct=Number(document.getElementById('dsr-percentual').value);if(!Number.isFinite(dsrPct)||dsrPct<0||dsrPct>100)throw Error('Informe DSR estimado entre 0% e 100%.');document.getElementById('dsr-taxa').textContent='Percentual simulado: '+dsrPct.toLocaleString('pt-BR')+'%';for(const taxa of [50,100]){const dsr=r['total'+taxa]*dsrPct/100;document.getElementById('dsr-'+taxa).textContent='Códs. 265 e 268 — DSR estimado ('+taxa+'% HE): '+money(dsr);document.getElementById('com-dsr-'+taxa).textContent='Total bruto estimado com DSR ('+taxa+'% HE): '+money(r['total'+taxa]+dsr);}document.getElementById('periodo-dobra').textContent=n?'Noturno em '+n+' de '+t+' hora(s) extra(s): 50% em dia comum e também em feriado, conforme a regra informada.':'Dobra sem adicional noturno.';document.getElementById('resumo-dobra').hidden=false;document.getElementById('vazio-dobra').hidden=true;document.getElementById('erro-dobra').hidden=true;}catch(e){limparDobra();document.getElementById('erro-dobra').textContent=e.message;document.getElementById('erro-dobra').hidden=false;}});\n\ndocument.getElementById('total-horas').addEventListener('change',()=>{const select=document.getElementById('horas-noturnas'),anterior=Number(select.value),total=Number(document.getElementById('total-horas').value);select.replaceChildren();for(let i=total;i>=1;i--){const option=document.createElement('option');option.value=String(i);option.textContent=i+' hora(s)'+(i===total?' — período inteiro':'');select.append(option);}select.value=String(Math.min(anterior,total));limparDobra();});\n\nfor(const id of ['salario','salario-dobra','adicionais'])document.getElementById(id).addEventListener('blur',()=>{const campo=document.getElementById(id);try{campo.value=lerDinheiro(campo.value).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});if(id==='salario'||id==='salario-dobra')document.getElementById(id==='salario'?'salario-dobra':'salario').value=campo.value;}catch{/* Keep invalid input for correction; submit shows the error. */}});\n</script><script>if(\"serviceWorker\" in navigator){window.addEventListener(\"load\",()=>navigator.serviceWorker.register(\"/sw.js\").catch(()=>{}));}(function(){const year=document.getElementById('escala-ano-futuro'),month=document.getElementById('escala-mes-futuro'),grade=document.getElementById('escala-grade-futuro'),title=document.getElementById('escala-titulo-futuro'),offLabel=document.getElementById('escala-folgas-futuro'),status=document.getElementById('escala-status-futuro');if(!year||!month||!grade)return;const names=[\"Janeiro\",\"Fevereiro\",\"Março\",\"Abril\",\"Maio\",\"Junho\",\"Julho\",\"Agosto\",\"Setembro\",\"Outubro\",\"Novembro\",\"Dezembro\"],approved=[\"yyyyyogggggobbbbboppppooyyyyogg\",\"gggobbbbbopppppoyyyyyoggggoo\",\"bbbbopppppoyyyyyogggggobbbbbopp\",\"ppooyyyyogggggobbbbbopppppoyyy\",\"yyoggggoobbbbopppppoyyyyyoggggg\",\"obbbbboppppooyyyyogggggobbbbbo\",\"pppppoyyyyyoggggoobbbbopppppoyy\",\"yyyogggggobbbbboppppooyyyyogggg\",\"gobbbbbopppppoyyyyyoggggoobbbb\",\"opppppoyyyyyogggggobbbbboppppoo\",\"yyyyogggggobbbbbopppppoyyyyyog\",\"gggoobbbbopppppoyyyyyogggggobbb\"];const weekdays=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];const pattern=[['o',2],[0,4],['o',1],[1,5],['o',1],[2,5],['o',1],[3,5],['o',1],[0,5],['o',1],[1,4]];const colors={y:'#f4d94b',g:'#59c579',b:'#5abbe7',p:'#e9acd2',o:'#f1f5f4'};const labels={y:'19h–01h',g:'13h–19h',b:'07h–13h',p:'01h–07h',o:'Folga'};const cycle=35;function shift(y,m,d){if(y===2027)return approved[m][d-1];const delta=Math.round((Date.UTC(y,m,d)-Date.UTC(2027,9,30))/86400000);const block=Math.floor(delta/cycle);let offset=((delta%cycle)+cycle)%cycle;const order=block%2===0?['y','g','b','p']:['b','p','y','g'];for(const [t,n]of pattern){if(offset<n)return t==='o'?'o':order[t];offset-=n}return'o'}function render(){const y=Number(year.value),m=Number(month.value),total=new Date(Date.UTC(y,m+1,0)).getUTCDate(),first=new Date(Date.UTC(y,m,1)).getUTCDay();title.textContent=names[m]+' de '+y;grade.replaceChildren();function cell(value,type,header){const el=document.createElement('div');el.textContent=value;if(header){el.style.cssText='text-align:center;font-size:14px;font-weight:800;padding:7px 0'}else if(type){el.title=labels[type];el.setAttribute('aria-label',value+' de '+names[m]+': '+labels[type]);el.style.cssText='background:'+colors[type]+';border:1px solid #9aafb0;border-radius:7px;min-height:43px;display:flex;align-items:center;justify-content:center;font-weight:750;color:#17363b'}grade.appendChild(el)}for(const d of weekdays)cell(d,null,true);for(let i=0;i<first;i++)cell('',null,false);const offs=[];for(let d=1;d<=total;d++){const t=shift(y,m,d);cell(String(d),t,false);if(t==='o')offs.push(d)}offLabel.textContent='Folgas: '+offs.join(', ')+'.';status.textContent=y===2027?'Escala de 2027 aprovada.':'Escala preliminar: confira as folgas com a escala oficial.';document.getElementById('escala-anterior-futuro').disabled=y===2027&&m===0;document.getElementById('escala-proximo-futuro').disabled=y===2030&&m===11}year.addEventListener('change',render);month.addEventListener('change',render);document.getElementById('escala-anterior-futuro').addEventListener('click',()=>{let y=Number(year.value),m=Number(month.value);if(m===0){if(y===2027)return;y--;m=11}else m--;year.value=String(y);month.value=String(m);render()});document.getElementById('escala-proximo-futuro').addEventListener('click',()=>{let y=Number(year.value),m=Number(month.value);if(m===11){if(y===2030)return;y++;m=0}else m++;year.value=String(y);month.value=String(m);render()});render()})();</script></body></html>";
export default { async fetch(request, env) { const url=new URL(request.url);if(url.pathname==="/apple-touch-icon.png"||url.pathname==="/apple-touch-icon-precomposed.png"){return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(""),c=>c.charCodeAt(0)),{headers:{"Content-Type":"image/png","Cache-Control":"public, max-age=3600"}});}const iconMatch=url.pathname.match(/^\/icons\/terberg-v4-(192|512)\.png$/);if(iconMatch){const data={"192":"","512":""}[iconMatch[1]];return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(data),c=>c.charCodeAt(0)),{headers:{"Content-Type":"image/png","Cache-Control":"public, max-age=31536000, immutable"}});} if(request.method!=="GET" && request.method!=="HEAD")return new Response("Método não permitido",{status:405,headers:{Allow:"GET, HEAD"}}); if(url.pathname==="/icon.webp"){const b=atob("");const bytes=Uint8Array.from(b,c=>c.charCodeAt(0));return new Response(request.method==="HEAD"?null:bytes,{headers:{"Content-Type":"image/webp","Cache-Control":"public, max-age=86400"}})}if(url.pathname==="/manifest.webmanifest")return new Response(JSON.stringify({name:"Meu PPR e Dobras",short_name:"Meu PPR",description:"Calculadora de PPR e dobras",start_url:"/",scope:"/",display:"standalone",background_color:"#f1f5f4",theme_color:"#153e44",id:"/",icons:[{src:"/icons/terberg-v4-192.png",sizes:"192x192",type:"image/png",purpose:"any maskable"},{src:"/icons/terberg-v4-512.png",sizes:"512x512",type:"image/png",purpose:"any maskable"}]}),{headers:{"Content-Type":"application/manifest+json; charset=utf-8","Cache-Control":"no-cache"}});if(url.pathname==="/icon.svg")return new Response('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="100" fill="#153e44"/><rect x="95" y="92" width="322" height="328" rx="32" fill="#f1f5f4"/><rect x="126" y="128" width="260" height="70" rx="12" fill="#c8dd54"/><text x="256" y="178" font-family="Arial,sans-serif" font-size="47" font-weight="bold" text-anchor="middle" fill="#153e44">PPR</text><g fill="#153e44"><rect x="130" y="232" width="66" height="52" rx="10"/><rect x="223" y="232" width="66" height="52" rx="10"/><rect x="316" y="232" width="66" height="52" rx="10"/><rect x="130" y="307" width="66" height="52" rx="10"/><rect x="223" y="307" width="66" height="52" rx="10"/><rect x="316" y="307" width="66" height="52" rx="10"/></g></svg>',{headers:{"Content-Type":"image/svg+xml","Cache-Control":"public, max-age=86400"}});if(url.pathname==="/sw.js")return new Response('const CACHE="meu-ppr-v6-full-icon";self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(["/","/manifest.webmanifest","/icon.webp"])));self.skipWaiting()});self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;const u=new URL(e.request.url);if(u.origin!==location.origin)return;if(u.pathname==="/api/config"){e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)));return}e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))})',{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"no-cache","Service-Worker-Allowed":"/"}});if(url.pathname==="/api/config") {try {const row=await env.DB.prepare("SELECT value FROM app_config WHERE key = ?").bind("ppr_2026").first();return Response.json(row?JSON.parse(row.value):{error:"Configuração indisponível"},{status:row?200:503,headers:{"Cache-Control":"public, max-age=3600"}});}catch {return Response.json({error:"Configuração indisponível"},{status:503});}} if(url.pathname!=="/"&&url.pathname!=="/index.html")return new Response("Página não encontrada",{status:404});return new Response(request.method==="HEAD"?null:HTML,{headers:{"Content-Type":"text/html; charset=utf-8","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","Content-Security-Policy":"default-src 'none'; manifest-src 'self'; worker-src 'self'; img-src data: 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'","Cache-Control":"no-cache"}}); }};
